from typing import Optional

HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")

# An HTML comment. The body may not contain "-->", so each match ends at the first close.
COMMENT = re.compile(r"<!--(?:(?!-->).)*-->", re.DOTALL)

# Placeholder left where a comment was removed, so the line it sat on can be tidied.
_MARK = ""


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def _strip_comments(text):
    """Remove HTML comments, returning the remaining text as a list of lines.

    Whitespace left at the end of a line by a removed comment is dropped.
    """
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = COMMENT.sub(_MARK, text)
    lines = []
    for line in text.split("\n"):
        if _MARK in line:
            line = line.replace(_MARK, "").rstrip()
        lines.append(line)
    return lines


def parse_changelog(text):
    releases = []
    current = None
    for line in _strip_comments(text):
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                raise ValueError(f"malformed release heading: {line!r}")
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def _tidy(lines):
    """Collapse runs of blank lines to one and trim blank lines at both ends."""
    out = []
    for line in lines:
        if line.strip() == "":
            if out and out[-1] == "":
                continue
            out.append("")
        else:
            out.append(line)
    while out and out[0] == "":
        out.pop(0)
    while out and out[-1] == "":
        out.pop()
    return out


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            title = f"# {release.version}"
            if release.date:
                title += f" ({release.date})"
            body = _tidy(release.body)
            if not body:
                return title + "\n"
            return f"{title}\n\n" + "\n".join(body) + "\n"
    raise LookupError(version)

